<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Str;
class Booking extends Model{protected $fillable=['reference','tour_id','tour_departure_id','pickup_point_id','type','status','first_name','last_name','phone','email','whatsapp','date_of_birth','age','address','participant_count','comments','special_requests','mobility_information','food_allergies','meal_selection','promo_code','source','emergency_contact_name','emergency_contact_phone','roommate_request','currency','total_amount','deposit_amount','amount_paid','payment_status','payment_proof','policies_accepted_at','confirmation_sent_at','seat_notice_sent_at'];public const PAYMENT_STATUSES=['unpaid'=>'Unpaid','proof_submitted'=>'Proof submitted','deposit_paid'=>'Deposit paid','paid'=>'Fully paid','refunded'=>'Refunded'];protected $casts=['date_of_birth'=>'date','age'=>'integer','total_amount'=>'decimal:2','deposit_amount'=>'decimal:2','amount_paid'=>'decimal:2','policies_accepted_at'=>'datetime','confirmation_sent_at'=>'datetime','seat_notice_sent_at'=>'datetime'];protected static function booted():void{static::creating(fn($m)=>$m->reference??='DT-'.strtoupper(Str::random(8)));}public function tour(){return $this->belongsTo(Tour::class);}public function departure(){return $this->belongsTo(TourDeparture::class,'tour_departure_id');}public function pickupPoint(){return $this->belongsTo(PickupPoint::class);}public function passengers(){return $this->hasMany(BookingPassenger::class)->orderBy('room_number')->orderBy('id');} public function getBalanceDueAttribute(): float{return max(0,(float)$this->total_amount-(float)$this->amount_paid);}}
